import { FileSessionStore, z } from 'genkit/beta';
import { ai } from './ai.js';
import { createRefund } from './db.js';
import { lookupOrder } from './tools.js';

const store = new FileSessionStore('.genkit/sessions');

const issueRefund = ai.defineTool(
  {
    name: 'issueRefund',
    description: 'Refunds an amount to the customer for an order. Only call this after approveRefund returned approved.',
    inputSchema: z.object({ orderId: z.string(), amount: z.number() }),
    outputSchema: z.object({ refundId: z.string() }),
  },
  async ({ orderId, amount }) => ({ refundId: createRefund(orderId, amount) }),
);

const approveRefund = ai.defineInterrupt({
  name: 'approveRefund',
  description: 'Asks a human to approve a refund before it is issued.',
  inputSchema: z.object({ orderId: z.string(), amount: z.number(), reason: z.string() }),
  outputSchema: z.object({ approved: z.boolean(), note: z.string().optional() }),
});

/** Answers order status questions. */
export const orderAgent = ai.defineAgent({
  name: 'orderAgent',
  description: 'Answers questions about an order: its status, delivery date, tracking code and total.',
  system:
    'You are the Northwind Supplies order desk. Answer questions about orders using the lookupOrder tool. ' +
    'Quote the status, ETA and tracking code exactly as the tool returns them. If an order is not found, say so.',
  tools: [lookupOrder],
  maxTurns: 4,
});

/** Handles refund requests and pauses for human approval before refunding. */
export const refundAgent = ai.defineAgent({
  name: 'refundAgent',
  description: 'Handles refund requests for an order. Refunds need human approval.',
  system: 'Look up the order, then call approveRefund, then issueRefund only if approved. Never refund without approval.',
  tools: [lookupOrder, approveRefund, issueRefund],
  toolChoice: 'auto',
  maxTurns: 6,
  store,
});

const handOffToOrderAgent = ai.defineTool(
  {
    name: 'handOffToOrderAgent',
    description: 'Hands an order question (status, delivery date, tracking, total) to the order desk and returns its answer.',
    inputSchema: z.object({ message: z.string().describe('The customer question, including the order id') }),
    outputSchema: z.string(),
  },
  async ({ message }) => (await orderAgent.chat().send(message)).text,
);

const handOffToRefundAgent = ai.defineTool(
  {
    name: 'handOffToRefundAgent',
    description: 'Hands a refund request to the refund desk and returns its answer.',
    inputSchema: z.object({ message: z.string().describe('The refund request, including the order id and reason') }),
    outputSchema: z.string(),
  },
  async ({ message }) => {
    const response = await refundAgent.chat().send(message);
    if (response.interrupts.length > 0) return 'The refund is waiting for human approval and has not been issued yet.';
    return response.text;
  },
);

/** Front desk the customer talks to first; hands order and refund requests to specialist agents. */
export const triage = ai.defineAgent({
  name: 'triage',
  description: 'Front desk for Northwind Supplies customers. Routes order and refund requests to specialist agents.',
  system:
    'You are the Northwind Supplies front desk. Greet the customer and find out what they need. ' +
    'Send order questions (status, delivery, tracking, total) to handOffToOrderAgent and refund requests to handOffToRefundAgent. ' +
    'Do not answer order or refund questions yourself. The specialists cannot see this conversation, so include the order id and the full request in the message you pass them.',
  tools: [handOffToOrderAgent, handOffToRefundAgent],
  maxTurns: 4,
  store,
});
